package conceptspace

// csLexAdapter implements the csLexer interface generated by goyacc.
type csLexAdapter struct {
	lex    *csLexerState
	result Space
	err    string
}

// Lex returns the next token for goyacc.
func (l *csLexAdapter) Lex(lval *csSymType) int {
	t := l.lex.next()
	switch t.typ {
	case csTokEOF:
		return 0
	case csTokSYMBOL:
		lval.str = t.val
		return CS_SYMBOL
	case csTokCOMMA:
		return CS_COMMA
	case csTokLPAREN:
		return CS_LPAREN
	case csTokRPAREN:
		return CS_RPAREN
	case csTokLBR:
		return CS_LBR
	case csTokRBR:
		return CS_RBR
	case csTokPLUS:
		return CS_PLUS
	case csTokTIMES:
		return CS_TIMES
	case csTokTILDA:
		return CS_TILDA
	default:
		return 0
	}
}

// Error is called by the generated parser on syntax errors.
func (l *csLexAdapter) Error(s string) {
	l.err = s
}
